'use client';

import React, { useState, useEffect } from 'react';
import styles from './combo-offers.module.css';
import { INITIAL_COMBO_OFFERS } from '@/lib/mockData';
import {
    Plus,
    Edit2,
    Trash2,
    Image as ImageIcon,
    X,
    Tag,
    FileText,
    IndianRupee,
    Link as LinkIcon,
    Package
} from 'lucide-react';

export default function AdminComboOffers() {
    const [offers, setOffers] = useState<any[]>([]);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingOffer, setEditingOffer] = useState<any>(null);
    const [formData, setFormData] = useState({
        name: '',
        description: '',
        price: '',
        offerPrice: '',
        image: '',
        products: [] as string[]
    });
    const [newItem, setNewItem] = useState('');

    const [imagePreview, setImagePreview] = useState<string | null>(null);

    // Load from localStorage on mount
    useEffect(() => {
        const savedOffers = localStorage.getItem('jk_combo_offers');
        if (savedOffers) {
            setOffers(JSON.parse(savedOffers));
        } else {
            setOffers(INITIAL_COMBO_OFFERS);
            localStorage.setItem('jk_combo_offers', JSON.stringify(INITIAL_COMBO_OFFERS));
        }
    }, []);

    // Save to localStorage whenever offers change
    const updateOffers = (newOffers: any[]) => {
        setOffers(newOffers);
        localStorage.setItem('jk_combo_offers', JSON.stringify(newOffers));
    };

    const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64String = reader.result as string;
                setFormData({ ...formData, image: base64String });
                setImagePreview(base64String);
            };
            reader.readAsDataURL(file);
        }
    };

    const handleOpenModal = (offer: any = null) => {
        if (offer) {
            setEditingOffer(offer);
            setFormData({
                name: offer.name,
                description: offer.description,
                price: offer.price.toString(),
                offerPrice: offer.offerPrice.toString(),
                image: offer.image,
                products: offer.products || []
            });
            setImagePreview(offer.image);
        } else {
            setEditingOffer(null);
            setFormData({ name: '', description: '', price: '', offerPrice: '', image: '', products: [] });
            setImagePreview(null);
        }
        setIsModalOpen(true);
    };

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();

        let newOffers;
        if (editingOffer) {
            newOffers = offers.map(o => o._id === editingOffer._id ? {
                ...o,
                ...formData,
                price: Number(formData.price),
                offerPrice: Number(formData.offerPrice)
            } as any : o);
        } else {
            const newOffer = {
                _id: Date.now().toString(),
                ...formData,
                price: Number(formData.price),
                offerPrice: Number(formData.offerPrice)
            } as any;
            newOffers = [...offers, newOffer];
        }

        updateOffers(newOffers);
        setIsModalOpen(false);
    };

    const handleDelete = (id: string) => {
        if (confirm('Delete this combo offer?')) {
            const newOffers = offers.filter(o => o._id !== id);
            updateOffers(newOffers);
        }
    };

    const handleReset = () => {
        if (confirm('Reset to default combo offers?')) {
            updateOffers(INITIAL_COMBO_OFFERS);
        }
    };

    const addProductItem = (e: any) => {
        e.preventDefault();
        if (newItem.trim()) {
            setFormData({ ...formData, products: [...formData.products, newItem.trim()] });
            setNewItem('');
        }
    };

    const removeProductItem = (index: number) => {
        const newProducts = [...formData.products];
        newProducts.splice(index, 1);
        setFormData({ ...formData, products: newProducts });
    };

    return (
        <div className={styles.container}>
            <div className={styles.header}>
                <div className={styles.headerTitle}>
                    <h1>Manage Combo Offers</h1>
                    <p>Create special deals and bundles for your customers</p>
                </div>
                <div className={styles.headerActions}>
                    <button className={styles.resetBtn} onClick={handleReset} title="Reset to Defaults">
                        Reset
                    </button>
                    <button className={styles.addBtn} onClick={() => handleOpenModal()}>
                        <Plus size={20} /> Add Combo
                    </button>
                </div>
            </div>

            <div className={styles.productGrid}>
                {offers.map((o) => (
                    <div key={o._id} className={styles.productCard}>
                        <div className={styles.productImg}>
                            {o.image ? (
                                <img src={o.image} alt={o.name} />
                            ) : (
                                <div className={styles.imgPlaceholder}>
                                    <ImageIcon size={48} />
                                </div>
                            )}
                            {o.price > o.offerPrice && (
                                <div className={styles.cardBadge}>
                                    {Math.round(((o.price - o.offerPrice) / o.price) * 100)}% OFF
                                </div>
                            )}
                        </div>
                        <div className={styles.productInfo}>
                            <h3>{o.name}</h3>
                            <p className={styles.desc}>{o.description}</p>
                            <div className={styles.priceContainer}>
                                <div className={styles.priceRow}>
                                    <span className={styles.finalPrice}>₹{o.offerPrice}</span>
                                    <span className={styles.originalPrice}>₹{o.price}</span>
                                </div>
                            </div>
                            <div className={styles.actions}>
                                <button className={styles.editBtn} onClick={() => handleOpenModal(o)}>
                                    <Edit2 size={16} /> Edit
                                </button>
                                <button className={styles.deleteBtn} onClick={() => handleDelete(o._id)}>
                                    <Trash2 size={16} />
                                </button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {isModalOpen && (
                <div className={styles.modalOverlay}>
                    <div className={styles.modal}>
                        <div className={styles.modalHeader}>
                            <div className={styles.modalTitleArea}>
                                <h2>{editingOffer ? 'Edit Combo Offer' : 'Add New Combo Offer'}</h2>
                                <p>{editingOffer ? 'Update offer details and pricing' : 'Create a new bundle deal'}</p>
                            </div>
                            <button className={styles.closeBtn} onClick={() => setIsModalOpen(false)}>
                                <X size={24} />
                            </button>
                        </div>
                        <form onSubmit={handleSave} className={styles.form}>
                            <div className={styles.formBody}>
                                <div className={styles.formLeft}>
                                    <div className={styles.inputGroup}>
                                        <label><Tag size={16} /> Offer Name</label>
                                        <div className={styles.inputWrapper}>
                                            <input
                                                type="text"
                                                placeholder="e.g. Family Feast"
                                                value={formData.name}
                                                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                                required
                                            />
                                        </div>
                                    </div>
                                    <div className={styles.inputGroup}>
                                        <label><FileText size={16} /> Description</label>
                                        <textarea
                                            placeholder="Describe what's in the combo..."
                                            value={formData.description}
                                            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                            required
                                        />
                                    </div>
                                    <div className={styles.row}>
                                        <div className={styles.inputGroup}>
                                            <label><IndianRupee size={16} /> Regular Price (₹)</label>
                                            <div className={styles.inputWrapper}>
                                                <input
                                                    type="number"
                                                    placeholder="0.00"
                                                    value={formData.price}
                                                    onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                                                    required
                                                />
                                            </div>
                                        </div>
                                        <div className={styles.inputGroup}>
                                            <label><IndianRupee size={16} /> Offer Price (₹)</label>
                                            <div className={styles.inputWrapper}>
                                                <input
                                                    type="number"
                                                    placeholder="0.00"
                                                    value={formData.offerPrice}
                                                    onChange={(e) => setFormData({ ...formData, offerPrice: e.target.value })}
                                                    required
                                                />
                                            </div>
                                        </div>
                                    </div>

                                    <div className={styles.inputGroup}>
                                        <label><Package size={16} /> Included Items (Optional list)</label>
                                        <div className={styles.row} style={{ marginBottom: '10px' }}>
                                            <input
                                                type="text"
                                                placeholder="Add product name..."
                                                value={newItem}
                                                onChange={(e) => setNewItem(e.target.value)}
                                                onKeyDown={(e) => { if (e.key === 'Enter') addProductItem(e); }}
                                            />
                                            <button type="button" onClick={addProductItem} className={styles.editBtn} style={{ background: '#e2e8f0' }}>Add</button>
                                        </div>
                                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
                                            {formData.products.map((item, idx) => (
                                                <div key={idx} style={{ background: '#f1f5f9', padding: '4px 8px', borderRadius: '6px', fontSize: '0.9rem', display: 'flex', alignItems: 'center', gap: '6px' }}>
                                                    {item}
                                                    <X size={14} style={{ cursor: 'pointer' }} onClick={() => removeProductItem(idx)} />
                                                </div>
                                            ))}
                                        </div>
                                    </div>

                                </div>

                                <div className={styles.formRight}>
                                    <div className={styles.imageUploadArea}>
                                        <label>Offer Image</label>
                                        <div className={styles.imagePreviewContainer}>
                                            {imagePreview ? (
                                                <>
                                                    <img src={imagePreview} alt="Preview" className={styles.previewImg} />
                                                    <button
                                                        type="button"
                                                        className={styles.removeImageBtn}
                                                        onClick={() => {
                                                            setImagePreview(null);
                                                            setFormData({ ...formData, image: '' });
                                                        }}
                                                    >
                                                        <X size={14} />
                                                    </button>
                                                </>
                                            ) : (
                                                <div className={styles.uploadPlaceholder}>
                                                    <ImageIcon size={40} />
                                                    <span>No image selected</span>
                                                </div>
                                            )}
                                        </div>
                                        <div className={styles.fileInputWrapper}>
                                            <input
                                                type="file"
                                                accept="image/*"
                                                onChange={handleImageUpload}
                                                id="offer-image"
                                                className={styles.fileInput}
                                            />
                                            <label htmlFor="offer-image" className={styles.uploadBtn}>
                                                <LinkIcon size={16} /> {imagePreview ? 'Change Image' : 'Upload Image'}
                                            </label>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className={styles.formActions}>
                                <button type="button" className={styles.cancelBtn} onClick={() => setIsModalOpen(false)}>Cancel</button>
                                <button type="submit" className={styles.saveBtn}>
                                    {editingOffer ? 'Update Combo' : 'Create Combo'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}
